query TvWatchInfo($viewableId: ID!) {
  playbackMetadata(viewableId: $viewableId) {
    viewableId
    title
    subtitle
    live
    video {
      __typename
      videoId
      title
      ... on Episode {
        parentShow {
          videoId
          title
        }
      }
    }
    channel {
      channelId
      name
      number
    }
    nextEpisode {
      videoId
    }
    previousChannel {
      channelId
    }
    nextChannel {
      channelId
    }
  }
}
